  await t.test('HTTP payer snapshot remains independent from seller after successful debit',async()=>{const p=await post('/v1/orders/'+orderC.id+'/capital-wallet-payments',{id:randomUUID(),memberId:buyerC,reference:'BUYER-C-PAY'},'unused');assert.equal(p.status,200);assert.equal((await p.json()).member_id,buyerC);assert.equal((await(await request('/v1/members/'+buyerC+'/capital-wallet')).json()).available,9900000);assert.equal((await(await request(walletPath)).json()).available,0);await gate;assert.equal((await db.query('SELECT member_id FROM sajada.sales_order WHERE id=$1',[orderC.id])).rows[0].member_id,memberA);});
  await t.test('SQL wallet records order facts and items immutable with tenant RLS',async()=>{await gate;for(const table of ['capital_wallet_activation','capital_wallet_payment']){await assert.rejects(db.query('DELETE FROM sajada.'+table+' WHERE tenant_id=$1',[tenantA]),/immutable|append|audit/i);await assert.rejects(db.query("UPDATE sajada."+table+" SET reference='Forged' WHERE tenant_id=$1",[tenantA]),/immutable|append|audit/i);}await assert.rejects(db.query("UPDATE sajada.sales_order SET status='pending' WHERE id=$1",[walletOrder.id]),/immutable/i);await assert.rejects(db.query('UPDATE sajada.order_item SET quantity=1 WHERE order_id=$1',[walletOrder.id]),/immutable/i);await db.exec('BEGIN;SET LOCAL ROLE http_test_api');try{await db.query("SELECT set_config('app.tenant_id',$1,true)",[tenantB]);assert.equal((await db.query('SELECT * FROM sajada.capital_wallet_payment WHERE tenant_id=$1',[tenantA])).rows.length,0);assert.equal((await db.query('SELECT * FROM sajada.capital_wallet_activation WHERE tenant_id=$1',[tenantA])).rows.length,0);}finally{await db.exec('ROLLBACK');}});

  let respendOrder;
  const refundPath='/v1/orders/'+orderC.id+'/capital-wallet-refunds',refundBody={id:randomUUID(),reference:'REFUND-C-1',reason:'Buyer cancelled before dispatch'};
  await t.test('HTTP wallet refund role tenant amount reason and dispatch constraints',async()=>{for(const role of ['accountant','member'])assert.equal((await request(refundPath,await token({roles:[role]}),tenantA,'POST',refundBody)).status,403);assert.equal((await request(refundPath,await token({tenant_ids:[tenantB]}),tenantB,'POST',refundBody)).status,404);assert.equal((await post(refundPath,{...refundBody,amount:1},'unused')).status,400);assert.equal((await post(refundPath,{...refundBody,reason:''},'unused')).status,400);assert.equal((await post('/v1/orders/'+walletOrder.id+'/capital-wallet-refunds',refundBody,'unused')).status,409);assert.equal((await post('/v1/orders/'+order.id+'/capital-wallet-refunds',refundBody,'unused')).status,404);});
  await t.test('HTTP refund failure atomically rolls back credit release journal cancellation and audit',async()=>{const before=await(await request('/v1/members/'+buyerC+'/capital-wallet')).json(),w=await(await request('/v1/inventory')).json();await gate;const journals=(await db.query('SELECT count(*)::int n FROM sajada.journal')).rows[0].n;await db.exec('REVOKE INSERT ON sajada.outbox FROM http_test_api');try{assert.equal((await post(refundPath,refundBody,'unused')).status,403);}finally{await gate;await db.exec('GRANT INSERT ON sajada.outbox TO http_test_api');}assert.deepEqual(await(await request('/v1/members/'+buyerC+'/capital-wallet')).json(),before);assert.deepEqual(await(await request('/v1/inventory')).json(),w);await gate;assert.equal((await db.query('SELECT count(*)::int n FROM sajada.journal')).rows[0].n,journals);assert.equal((await db.query('SELECT status FROM sajada.sales_order WHERE id=$1',[orderC.id])).rows[0].status,'paid');});
  await t.test('HTTP full refund restores original payer only preserves fees cash funding and original payment with exact retry',async()=>{const before=await(await request('/v1/members/'+buyerC+'/capital-wallet')).json(),cap=await(await request('/v1/members/'+buyerC+'/capital')).json(),cash=(await apSnapshot()).cash,w=await(await request('/v1/inventory')).json();for(let i=0;i<2;i++){const r=await post(refundPath,refundBody,'unused');assert.equal(r.status,200);const f=await r.json();assert.equal(f.member_id,buyerC);assert.equal(Number(f.amount),100000);assert.equal(f.actor,'test-admin');}const after=await(await request('/v1/members/'+buyerC+'/capital-wallet')).json();assert.equal(after.available,10000000);assert.equal(after.refunded,100000);assert.equal(after.grossSpent,100000);assert.equal(after.spent,0);assert.deepEqual(after.payments,before.payments);assert.deepEqual(after.activation,before.activation);assert.deepEqual(await(await request('/v1/members/'+buyerC+'/capital')).json(),cap);assert.equal((await(await request(walletPath)).json()).available,0);assert.equal((await apSnapshot()).cash,cash);const aw=await(await request('/v1/inventory')).json(),bal=s=>s.balances.find(b=>b.productId===walletProduct&&b.locationId===depot);assert.equal(bal(aw).onHand,bal(w).onHand);assert.equal(bal(aw).reserved,bal(w).reserved-1);assert.equal(aw.documents.find(d=>d.kind==='reserve'&&d.reference===orderC.id).status,'cancelled');for(const patch of [{id:randomUUID()},{reason:'Other'},{reference:'Changed'}])assert.equal((await post(refundPath,{...refundBody,...patch},'unused')).status,409);await gate;const o=(await db.query('SELECT status,cancel_reason FROM sajada.sales_order WHERE id=$1',[orderC.id])).rows[0];assert.equal(o.status,'cancelled');assert.equal(o.cancel_reason,refundBody.reason);assert.equal((await db.query("SELECT count(*)::int n FROM sajada.outbox WHERE event_type='capital.wallet.order.refunded'")).rows[0].n,1);});
  await t.test('HTTP refunded order cannot dispatch receive pay again or redirect refund',async()=>{assert.equal((await post('/v1/orders/'+orderC.id+'/dispatch',{reference:'BAD-DISPATCH'},'unused')).status,409);assert.equal((await post('/v1/orders/'+orderC.id+'/receive',{reference:'BAD-RECEIVE',receiver:'Buyer'},'unused')).status,409);assert.equal((await post('/v1/orders/'+orderC.id+'/capital-wallet-payments',{id:randomUUID(),memberId:buyerC,reference:'PAY-AGAIN'},'unused')).status,409);assert.equal((await post(refundPath,{...refundBody,memberId:memberA},'unused')).status,400);});
